def plot_auc_preprocess_DWRF(recalls, pres):
    mean_recall = np.linspace(0, 1, 2000).tolist()
    pre = np.interp([1-x for x in mean_recall], [1-x for x in recalls], pres).tolist()
    pre[0] = 1.0
    # print('mean_tpr', mean_tpr)
    return pre
# print('pre_DWRF', plot_auc_preprocess_DWRF(recall_DWRF, pre_DWRF))
# print('pre_DeepDRM', plot_auc_preprocess_DWRF(recall_DeepDRM, pre_DeepDRM))


def plot_auc_preprocess(recalls, pres):
    mean_recall = np.linspace(0, 1, 2000).tolist()
    pre = []

    for i in range(len(recalls)):
        pre.append(np.interp([1-x for x in mean_recall], [1-x for x in recalls[i]], pres[i]))
        pre[-1][0] = 1
    mean_fpr = np.mean(pre, axis=0)
    mean_fpr[-1] = 0
    # print('mean_tpr', mean_tpr)
    return mean_fpr.tolist()
