# ROC对比实验
def plot_PR_curves(PRE):
    mean_recall = np.linspace(0, 1, 2000)
    plt.plot(mean_recall, PRE[0], color='#cb0000', alpha=1, linewidth=1.5, label='AGKformer(AUPR=%.4f)' % 0.9734)
    plt.plot(mean_recall, PRE[1], alpha=0.7, linewidth=1,  linestyle='--', label='MDBIRW(AUPR=%.4f)' % 0.9002)
    # plt.plot(mean_recall, PRE[2], alpha=0.4, linestyle='--', label='RCNMF(AUC=%.4f)' % 0.9526)
    plt.plot(mean_recall, PRE[2], alpha=0.7, linewidth=1,  linestyle='--', label='DWRF(AUPR=%.4f)' % 0.9515)
    plt.plot(mean_recall, PRE[3], alpha=0.7, linewidth=1,  linestyle='--', label='DeepDRM(AUPR=%.4f)' % 0.948897600094308)
    plt.plot(mean_recall, PRE[4], alpha=0.7, linewidth=1,  linestyle='--', label='GCNAT(AUPR=%.4f)' % 0.9514)
    plt.plot(mean_recall, PRE[5], alpha=0.7, linewidth=1,  linestyle='--', label='MDA-AENMF(AUPR=%.4f)' % 0.96269349)

    plt.plot([1, 0], [0, 1], linestyle='--', color='black', alpha=0.4)
    plt.xticks(fontsize=10)
    plt.yticks(fontsize=10)
